    53→/**
    54→ */
    55→public class JsonConfigurator
    56→{
    57→  private static final Logger log = new Logger(JsonConfigurator.class);
    58→
    59→  private final ObjectMapper jsonMapper;
    60→  private final Validator validator;
    61→
    62→  @Inject
    63→  public JsonConfigurator(
    64→      ObjectMapper jsonMapper,
    65→      Validator validator
    66→  )
    67→  {
    68→    this.jsonMapper = jsonMapper;
    69→    this.validator = validator;
    70→  }
    71→
    72→  public <T> T configurate(Properties props, String propertyPrefix, Class<T> clazz) throws ProvisionException
    73→  {
    74→    return configurate(props, propertyPrefix, clazz, null);
    75→  }
    76→
    77→  public <T> T configurate(
    78→      Properties props,
    79→      String propertyPrefix,
    80→      Class<T> clazz,
    81→      @Nullable Class<? extends T> defaultClass
    82→  ) throws ProvisionException
    83→  {
    84→    verifyClazzIsConfigurable(jsonMapper, clazz, defaultClass);
    85→
    86→    // Make it end with a period so we only include properties with sub-object thingies.
    87→    final String propertyBase = propertyPrefix.endsWith(".") ? propertyPrefix : propertyPrefix + ".";
    88→
    89→    Map<String, Object> jsonMap = new HashMap<>();
    90→    for (String prop : props.stringPropertyNames()) {
    91→      if (prop.startsWith(propertyBase)) {
    92→        final String propValue = props.getProperty(prop);
    93→        Object value;
    94→        try {
    95→          // If it's a String Jackson wants it to be quoted, so check if it's not an object or array and quote.
    96→          String modifiedPropValue = propValue;
    97→          if (!(modifiedPropValue.startsWith("[") || modifiedPropValue.startsWith("{"))) {
    98→            modifiedPropValue = jsonMapper.writeValueAsString(propValue);
    99→          }
   100→          value = jsonMapper.readValue(modifiedPropValue, Object.class);
   101→        }
   102→        catch (IOException e) {
   103→          log.info(e, "Unable to parse [%s]=[%s] as a json object, using as is.", prop, propValue);
   104→          value = propValue;
   105→        }
   106→        hieraricalPutValue(propertyPrefix, prop, prop.substring(propertyBase.length()), value, jsonMap);
   107→      }
   108→    }
   109→
   110→    final T config;
   111→    try {
   112→      if (defaultClass != null && jsonMap.isEmpty()) {
   113→        // No configs were provided. Don't use the jsonMapper; instead create a default instance of the default class
   114→        // using the no-arg constructor. We know it exists because verifyClazzIsConfigurable checks for it.
   115→        config = defaultClass.getConstructor().newInstance();
   116→      } else {
   117→        config = jsonMapper.convertValue(jsonMap, clazz);
   118→      }
   119→    }
   120→    catch (IllegalArgumentException e) {
   121→      throw new ProvisionException(
   122→          StringUtils.format("Problem parsing object at prefix[%s]: %s.", propertyPrefix, e.getMessage()), e
   123→      );
   124→    }
   125→    catch (NoSuchMethodException | InstantiationException | IllegalAccessException | InvocationTargetException e) {
   126→      throw new ProvisionException(
   127→          StringUtils.format(
   128→              "Problem instantiating object at prefix[%s]: %s: %s.",
   129→              propertyPrefix,
   130→              e.getClass().getSimpleName(),
   131→              e.getMessage()
   132→          ),
   133→          e
   134→      );
   135→    }
   136→
   137→    final Set<ConstraintViolation<T>> violations = validator.validate(config);
   138→    if (!violations.isEmpty()) {
   139→      List<String> messages = new ArrayList<>();
   140→
   141→      for (ConstraintViolation<T> violation : violations) {
   142→        StringBuilder path = new StringBuilder();
   143→        try {
   144→          Class<?> beanClazz = violation.getRootBeanClass();
   145→          final Iterator<Path.Node> iter = violation.getPropertyPath().iterator();
   146→          while (iter.hasNext()) {
   147→            Path.Node next = iter.next();
   148→            if (next.getKind() == ElementKind.PROPERTY) {
   149→              final String fieldName = next.getName();
   150→              final Field theField = beanClazz.getDeclaredField(fieldName);
   151→
   152→              if (theField.getAnnotation(JacksonInject.class) != null) {
   153→                path = new StringBuilder(StringUtils.format(" -- Injected field[%s] not bound!?", fieldName));
   154→                break;
   155→              }
   156→
   157→              JsonProperty annotation = theField.getAnnotation(JsonProperty.class);
   158→              final boolean noAnnotationValue = annotation == null || Strings.isNullOrEmpty(annotation.value());
   159→              final String pathPart = noAnnotationValue ? fieldName : annotation.value();
   160→              if (path.length() == 0) {
   161→                path.append(pathPart);
   162→              } else {
   163→                path.append(".").append(pathPart);
   164→              }
   165→            }
   166→          }
   167→        }
   168→        catch (NoSuchFieldException e) {
   169→          throw new RuntimeException(e);
   170→        }
   171→
   172→        messages.add(StringUtils.format("%s - %s", path.toString(), violation.getMessage()));
   173→      }
   174→
   175→      throw new ProvisionException(
   176→          Iterables.transform(
   177→              messages,
   178→              new Function<String, Message>()
   179→              {
   180→                @Override
   181→                public Message apply(String input)
   182→                {
   183→                  return new Message(StringUtils.format("%s%s", propertyBase, input));
   184→                }
   185→              }
   186→          )
   187→      );
   188→    }
   189→
   190→    log.debug("Loaded class[%s] from props[%s] as [%s]", clazz, propertyBase, config);
   191→
   192→    return config;
   193→  }
   194→
   195→  private static void hieraricalPutValue(
   196→      String propertyPrefix,
   197→      String originalProperty,
   198→      String property,
   199→      Object value,
   200→      Map<String, Object> targetMap
   201→  )
   202→  {
   203→    int dotIndex = property.indexOf('.');
   204→    // Always put property with name even if it is of form a.b. This will make sure the property is available for classes
   205→    // where JsonProperty names are of the form a.b
   206→    // Note:- this will cause more than required properties to be present in the jsonMap.
   207→    targetMap.put(property, value);
   208→    if (dotIndex < 0) {
   209→      return;
   210→    }
   211→    if (dotIndex == 0) {
   212→      throw new ProvisionException(StringUtils.format("Double dot in property: %s", originalProperty));
   213→    }
   214→    if (dotIndex == property.length() - 1) {
   215→      throw new ProvisionException(StringUtils.format("Dot at the end of property: %s", originalProperty));
   216→    }
   217→    String nestedKey = property.substring(0, dotIndex);
   218→    Object nested = targetMap.computeIfAbsent(nestedKey, k -> new HashMap<String, Object>());
   219→    if (!(nested instanceof Map)) {
   220→      // Clash is possible between properties, which are used to configure different objects: e. g.
   221→      // druid.emitter=parametrized is used to configure Emitter class, and druid.emitter.parametrized.xxx=yyy is used
   222→      // to configure ParametrizedUriEmitterConfig object. So skipping xxx=yyy key-value pair when configuring Emitter
   223→      // doesn't make any difference. That is why we just log this situation, instead of throwing an exception.
   224→      log.info(
   225→          "Skipping %s property: one of it's prefixes is also used as a property key. Prefix: %s",
   226→          originalProperty,
   227→          propertyPrefix
   228→      );
   229→      return;
   230→    }
   231→    Map<String, Object> nestedMap = (Map<String, Object>) nested;
   232→    hieraricalPutValue(propertyPrefix, originalProperty, property.substring(dotIndex + 1), value, nestedMap);
   233→  }
   234→
   235→  @VisibleForTesting
   236→  public static <T> void verifyClazzIsConfigurable(
   237→      ObjectMapper mapper,
   238→      Class<T> clazz,
   239→      @Nullable Class<? extends T> defaultClass
   240→  )
   241→  {
   242→    if (defaultClass != null) {
   243→      try {
   244→        defaultClass.getConstructor();
   245→      }
   246→      catch (NoSuchMethodException e) {
   247→        throw new ProvisionException(
   248→            StringUtils.format(
   249→                "JsonConfigurator requires default classes to have zero-arg constructors. %s doesn't",
   250→                defaultClass
   251→            )
   252→        );
   253→      }
   254→    }
   255→
   256→    final List<BeanPropertyDefinition> beanDefs = mapper.getSerializationConfig()
   257→                                                        .introspect(mapper.constructType(clazz))
   258→                                                        .findProperties();
   259→    for (BeanPropertyDefinition beanDef : beanDefs) {
   260→      final AnnotatedField field = beanDef.getField();
   261→      if (field == null || !field.hasAnnotation(JsonProperty.class)) {
   262→        throw new ProvisionException(
   263→            StringUtils.format(
   264→                "JsonConfigurator requires Jackson-annotated Config objects to have field annotations. %s doesn't",
   265→                clazz
   266→            )
   267→        );
   268→      }
   269→    }
   270→  }
   271→}
